package com.muthumol.player.dummy;
import java.util.*;import java.io.*;import java.util.zip.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=25)
public class PlaybackUpgradeTest {
 Movie movie(String name,String id){Movie m=new Movie();m.title=name;m.identity=id;m.uri="file:///"+id;m.chatId=-100;m.messageId=Math.abs(id.hashCode())+1;return m;}
 @Test public void completeShowHas117RowsWithCopiesKeptAsVersions(){List<Movie> files=new ArrayList<>();int[] counts={25,24,23,14,15,16};for(int s=1;s<=6;s++)for(int e=1;e<=counts[s-1];e++)for(int q:new int[]{720,1080})files.add(movie(String.format(Locale.US,"Lost.2004.S%02dE%02d.%dp.mkv",s,e,q),s+"_"+e+"_"+q));Movie selected=files.get(1);List<Movie> episodes=TvLibrary.episodes(files,selected);assertEquals(117,episodes.size());assertEquals(6,TvLibrary.seasons(files,selected).size());assertEquals(2,SeriesCatalog.copies(files,selected).size());Movie next=TvLibrary.neighbour(files,selected,1);assertEquals(2,MediaTitle.parse(next.title).episode);assertEquals("1080p",SeriesCatalog.quality(next));assertEquals(1,MediaTitle.parse(TvLibrary.neighbour(files,next,-1).title).episode);}
 @Test public void remakesAndOtherShowsNeverJoinEpisodeQueue(){Movie original=movie("Lost.2004.S01E01.mkv","old");assertEquals(1,TvLibrary.episodes(Arrays.asList(original,movie("Lost.2026.S01E02.mkv","new"),movie("Lost City.S01E02.mkv","other")),original).size());}
 @Test public void subtitleMatchingRequiresExactEpisodeAndCompatibleYear(){Movie m=movie("Lost.2004.S01E03.1080p.mkv","x");assertTrue(AutoSubtitles.score(m,"Lost.S01E03.Malayalam.srt","")>=0);assertTrue(AutoSubtitles.score(m,"Lost.S01E04.srt","")<0);assertTrue(AutoSubtitles.score(m,"Lost.S02E03.srt","")<0);assertTrue(AutoSubtitles.score(m,"Lost.2026.S01E03.srt","")<0);assertTrue(AutoSubtitles.score(m,"Other.S01E03.srt","")<0);assertTrue(AutoSubtitles.score(m,"English.srt","Lost S01E03")>=0);}
 @Test public void zipSeasonPackSelectsOneCorrectEpisodeWithoutWritingPaths()throws Exception{Movie m=movie("Lost.S01E02.mkv","zip");ByteArrayOutputStream data=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(data)){for(int e=1;e<=3;e++){z.putNextEntry(new ZipEntry("../Lost.S01E0"+e+".srt"));z.write(("1\n00:00:01,000 --> 00:00:02,000\nepisode "+e).getBytes("UTF-8"));z.closeEntry();}}AutoSubtitles.Packed result=AutoSubtitles.unpack(data.toByteArray(),m,"Lost.Season.1.zip");assertNotNull(result);assertEquals("Lost.S01E02.srt",result.name);assertTrue(new String(result.bytes,"UTF-8").endsWith("episode 2"));assertNull(AutoSubtitles.unpack(data.toByteArray(),movie("Lost.S02E01.mkv","bad"),"Lost.Season.1.zip"));}
 @Test public void zipBombStopsBeforeAllocatingUnboundedSubtitle()throws Exception{ByteArrayOutputStream data=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(data)){z.putNextEntry(new ZipEntry("Lost.S01E01.srt"));byte[] block=new byte[8192];for(int i=0;i<513;i++)z.write(block);z.closeEntry();}try{AutoSubtitles.unpack(data.toByteArray(),movie("Lost.S01E01.mkv","big"),"Lost.Season.1.zip");fail("Oversized subtitle accepted");}catch(IOException expected){}}
 @Test public void verticalVolumeGestureDoesNotClassifyHorizontalSwipeAsVolume(){assertTrue(PlayerGestures.vertical(5,60,24));assertTrue(PlayerGestures.vertical(-5,-60,24));assertFalse(PlayerGestures.vertical(80,30,24));assertFalse(PlayerGestures.vertical(1,10,24));}
 @Test public void newerUnwatchedRecordWinsOverOlderWatched()throws Exception{JSONObject old=new JSONObject().put("updated",100).put("watched",true),next=new JSONObject().put("updated",200).put("watched",false);assertSame(next,WatchSync.newer(old,next));assertSame(next,WatchSync.newer(next,old));}
 @Test public void watchedBadgeIsSharedByEpisodeCopiesAndCanBeCleared(){android.content.Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("tv-library",0).edit().clear().commit();TvLibrary library=new TvLibrary(c);Movie a=movie("Lost.S01E01.720p.mkv","a"),b=movie("Lost.S01E01.1080p.mkv","b");library.toggle(a,"watched");assertTrue(library.marked(b,"watched"));library.toggle(b,"watched");assertFalse(library.marked(a,"watched"));}
 @Test public void legacyWatchedEpisodeRemainsMarkedUntilExplicitlyCleared(){android.content.Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("tv-library",0).edit().clear().commit();TvLibrary library=new TvLibrary(c);Movie a=movie("Lost.2004.S01E01.720p.mkv","legacy");library.p.edit().putBoolean("episode-watched:2004:"+SeriesCatalog.episodeKey(a),true).commit();assertTrue(library.marked(a,"watched"));library.toggle(a,"watched");assertFalse(library.marked(a,"watched"));}
 @Test public void syncRecordNeverContainsDeviceFileIdOrPrivateUri()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();Movie m=movie("Lost.S01E01.mkv","sync");m.fileId=999;m.uri="tg://device-private";WatchSync sync=WatchSync.get(c);sync.record(m,123000,3600000,true);JSONObject saved=sync.local(WatchSync.key(m));assertEquals(123000,saved.getLong("position"));assertTrue(saved.getBoolean("watched"));assertFalse(saved.has("file"));assertFalse(saved.has("uri"));}
 @Test public void subtitleDownloadsRefuseForeignHosts()throws Exception{assertTrue(MsoneSubtitles.allowed(new java.net.URL("https://addon.malayalamsubtitles.org/subtitles/movie/tt1.json")));assertFalse(MsoneSubtitles.allowed(new java.net.URL("https://malayalamsubtitles.org.attacker.test/file.srt")));assertFalse(MsoneSubtitles.allowed(new java.net.URL("http://malayalamsubtitles.org/file.srt")));}
}
